alter table public.coach_decisions add column if not exists scope text not null default 'current_program',add column if not exists proposed_state jsonb,add column if not exists evidence_references jsonb not null default '[]',add column if not exists source text not null default 'engine',add column if not exists confidence numeric check(confidence between 0 and 1),add column if not exists confirmation_required boolean not null default false,add column if not exists confirmation_status text not null default 'committed' check(confirmation_status in('not_required','pending','confirmed','cancelled','committed'));
create table public.weekly_checkins(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,profile_snapshot_id uuid references public.personalization_profile_snapshots(id) on delete restrict,week_start date not null,weight_lb numeric check(weight_lb between 70 and 700),workout_adherence smallint not null check(workout_adherence between 0 and 100),nutrition_adherence smallint check(nutrition_adherence between 0 and 100),energy smallint not null check(energy between 1 and 5),sleep smallint not null check(sleep between 1 and 5),hunger smallint check(hunger between 1 and 5),stress smallint not null check(stress between 1 and 5),soreness smallint not null check(soreness between 1 and 5),difficulty smallint not null check(difficulty between 1 and 5),pain boolean not null default false,schedule_changed boolean not null default false,private_note text check(char_length(private_note)<=2000),submitted_at timestamptz not null default now(),unique(user_id,week_start));create index weekly_checkins_owner_time_idx on public.weekly_checkins(user_id,week_start desc);create index weekly_checkins_profile_idx on public.weekly_checkins(profile_snapshot_id);
create table public.weekly_coach_assessments(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,checkin_id uuid not null references public.weekly_checkins(id) on delete cascade,status jsonb not null,actions jsonb not null,reason_codes text[] not null,engine_version text not null,ruleset_version text not null,created_at timestamptz not null default now(),unique(checkin_id));create index weekly_assessments_owner_time_idx on public.weekly_coach_assessments(user_id,created_at desc);
create table public.plan_adjustment_requests(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,intent text not null check(intent in('traveling','different_equipment','schedule_changed','short_on_time','extra_rest_day','pain','other')),explicit_context jsonb not null default '{}',inferred_candidates jsonb not null default '[]',scope text not null check(scope in('session_only','date_range','week','current_program','until_changed','persistent')),starts_on date,ends_on date,safety_classification public.safety_classification not null default 'normal',proposal jsonb,reason_codes text[] not null default '{}',confirmation_status text not null default 'pending' check(confirmation_status in('pending','confirmed','cancelled','blocked')),created_at timestamptz not null default now(),decided_at timestamptz);create index adjustment_requests_owner_idx on public.plan_adjustment_requests(user_id,created_at desc);
create table public.reassessments(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,profile_snapshot_id uuid references public.personalization_profile_snapshots(id) on delete restrict,period_start date not null,period_end date not null,summary jsonb not null,recommendations jsonb not null,reason_codes text[] not null,engine_version text not null,ruleset_version text not null,confirmation_status text not null default 'pending',created_at timestamptz not null default now());create index reassessments_owner_time_idx on public.reassessments(user_id,created_at desc);create index reassessments_profile_idx on public.reassessments(profile_snapshot_id);
do $$ declare t text;begin foreach t in array array['weekly_checkins','weekly_coach_assessments','plan_adjustment_requests','reassessments'] loop execute format('alter table public.%I enable row level security',t);execute format('create policy %I on public.%I for select to authenticated using ((select auth.uid())=user_id)',t||'_select_own',t);execute format('create policy %I on public.%I for insert to authenticated with check ((select auth.uid())=user_id)',t||'_insert_own',t);execute format('create policy %I on public.%I for update to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id)',t||'_update_own',t);execute format('grant select,insert,update on public.%I to authenticated',t);end loop;end $$;
